#!/usr/bin/env python3
"""
generate_frames.py — Convert dancing-banana GIF PROGMEM bitmaps to
STM32 SSD1315 OLED page-format C arrays.

Usage
-----
1. Paste the byte content of each epd_bitmap_frame_N_delay_0 array into
   the FRAME_RAW dict below (the hex bytes inside the braces).
2. Run:  python generate_frames.py
3. The script overwrites  Core/Src/banana_frames.c  in this project.
4. Rebuild the STM32 project — the OLED will show the real GIF frames.

Source format:  249 x 246 px, 1-bpp, MSB-first, 32 bytes per row.
                Bit = 1 → white/background,  bit = 0 → dark/figure.
Target format:  128 x 64 px, SSD1315 page-mode.
                fb[page][col]: bit n = row (page*8 + n), lit when set.
"""

import re, os, textwrap

SRC_W, SRC_H     = 249, 246
SRC_ROW_BYTES    = 32          # ceil(249/8) with 7 padding bits at end
OUT_W, OUT_H     = 128, 64
OUT_PAGES        = OUT_H // 8  # 8

