# ──────────────────────────────────────────────────────────────────


def parse_bytes(raw: str) -> bytes:
    """Extract all 0xNN hex bytes from a C array literal string."""
    return bytes(int(x, 16) for x in re.findall(r'0x([0-9a-fA-F]{2})', raw))


def get_pixel(data: bytes, x: int, y: int) -> int:
    """Return 1 (white/off) or 0 (dark/on) for source pixel (x, y)."""
    idx = y * SRC_ROW_BYTES + x // 8
    if idx >= len(data):
        return 1  # treat out-of-bounds as white background
    return (data[idx] >> (7 - x % 8)) & 1


def scale_frame(data: bytes):
    """
    Nearest-neighbour downscale 249x246 → 128x64.
    Returns pages[8][128] in SSD1315 page-mode format.
    Source 0 (dark) maps to OLED bit set (pixel lit).
    Source 1 (white) maps to OLED bit clear (pixel off).
    """
    pages = [[0] * OUT_W for _ in range(OUT_PAGES)]
    for oy in range(OUT_H):
        sy = oy * SRC_H // OUT_H
        for ox in range(OUT_W):
            sx = ox * SRC_W // OUT_W
            if get_pixel(data, sx, sy) == 0:   # dark pixel → ON
                pages[oy // 8][ox] |= 1 << (oy % 8)
    return pages


def main():
    script_dir = os.path.dirname(os.path.abspath(__file__))
    out_path   = os.path.join(script_dir, 'Core', 'Src', 'banana_frames.c')

    scaled = []
    for fi in sorted(FRAME_RAW):
        raw  = FRAME_RAW[fi]
        data = parse_bytes(raw)
        expected = SRC_ROW_BYTES * SRC_H
        if len(data) < expected:
            print(f'WARNING: frame {fi} has {len(data)} bytes, expected {expected}.'
                  f'  Did you paste the full array?')
        scaled.append(scale_frame(data))
        print(f'Processed frame {fi}  ({len(data)} bytes)')

    with open(out_path, 'w') as f:
        f.write('#include "banana_frames.h"\n\n')
        f.write('/* Auto-generated by generate_frames.py — do not hand-edit. */\n\n')
        f.write('const uint8_t BANANA_FRAMES_READY = 1;\n\n')
        f.write('const uint8_t banana_frames'
                '[BANANA_FRAME_COUNT][BANANA_FRAME_PAGES][BANANA_FRAME_COLS] = {\n')
        for fi, pages in enumerate(scaled):
            f.write(f'    /* frame {fi} */\n    {{\n')
            for pi, row in enumerate(pages):
                hex_vals = ', '.join(f'0x{b:02x}' for b in row)
                f.write(f'        /* page {pi} */ {{ {hex_vals} }},\n')
            f.write('    },\n')
        f.write('};\n')

    n = len(scaled)
    total_bytes = n * OUT_PAGES * OUT_W
    print(f'\nWrote {out_path}')
    print(f'{n} frames  x  {OUT_PAGES} pages  x  {OUT_W} cols  =  {total_bytes} bytes flash')
    print('Rebuild the STM32 project to use the real GIF frames.')


if __name__ == '__main__':
    main()
